{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    allocations = [min(segment["minimum"], segment["capacity"]) for segment in segments]
    remaining = budget - sum(allocations)

    if remaining > 0:
        order = sorted(range(len(segments)), key=lambda i: (-segments[i]["importance"], i))
        for i in order:
            if remaining <= 0:
                break
            available = max(0, segments[i]["capacity"] - allocations[i])
            added = min(available, remaining)
            allocations[i] += added
            remaining -= added
    elif remaining < 0:
        order = sorted(range(len(segments)), key=lambda i: (segments[i]["importance"], -i))
        for i in order:
            if remaining >= 0:
                break
            removed = min(allocations[i], -remaining)
            allocations[i] -= removed
            remaining += removed

    return {
        "allocations": allocations,
        "by_name": {segment["name"]: allocations[i] for i, segment in enumerate(segments)},
        "total": sum(allocations),
    }
"}
